package hu.boltseged.account;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/account/password") public class AccountPasswordController {final AccountRepository repo;final PasswordEncoder encoder;AccountPasswordController(AccountRepository r,PasswordEncoder e){repo=r;encoder=e;}@PostMapping void change(@Valid @RequestBody Change x){Account a=(Account)SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!encoder.matches(x.currentPassword(),a.getPasswordHash()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A jelenlegi jelszó hibás.");a.setPasswordHash(encoder.encode(x.newPassword()));repo.save(a);}record Change(@NotBlank String currentPassword,@NotBlank @Size(min=12)String newPassword){}}
